// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public {
        c = new RoundFactory();
        c.initialize(); // owner is this test contract
    }
    function testFuzz_property(address impl) public {
        vm.assume(impl != address(0));
        bool ok = true;
        vm.prank(address(this));
        try c.updateRoundImplementation(payable(impl)) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok && c.roundImplementation() == impl);
    }
}
